Transform the attached character into a bust-up chess piece. Maintain everything as is except for the style, color, and material.
Style: {argument name="style" default="realistic 3DCG"}
Color: {argument name="color" default="solid ivory / matte black"}
Material: {argument name="material" default="polystone"}

{
    "subject": {
      "reference_image": "uploaded_image",
      "preserve_identity": true,
      "description": "Use the uploaded image as the exact subject reference. Keep facial structure, hairstyle, beard, skin tone, body proportions, sunglasses, and overall appearance consistent with the reference."
    },
    "outfit": {
      "style": "{argument name="clothing style" default="oversized avant-garde streetwear"}",
      "shirt": "extra oversized white button-up shirt with exaggerated balloon sleeves",
      "pants": "ultra baggy pale sage green denim jeans pooling over sneakers",
      "footwear": "white chunky sneakers",
